  `recommendation_id` int NOT NULL,
  `rank` smallint NOT NULL,
  `crop_name` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL,
  `recommendation_score` float NOT NULL,
  `agronomic_score` float NOT NULL,
  `seasonal_score` float NOT NULL,
  `price_score` float DEFAULT NULL,
  `price_available` tinyint(1) NOT NULL,
  `predicted_price` decimal(12,2) DEFAULT NULL,
  `expected_price_trend` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `explanation` json DEFAULT NULL,
  `timing_score` float DEFAULT NULL,
  `profit_score` float DEFAULT NULL,
  `expected_revenue` float DEFAULT NULL,
  `expected_cost` float DEFAULT NULL,
  `expected_profit` float DEFAULT NULL,
  `recommended` tinyint(1) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_recommendation_rank` (`recommendation_id`,`rank`),
  KEY `ix_recommendation_results_recommendation_id` (`recommendation_id`),
  CONSTRAINT `recommendation_results_ibfk_1` FOREIGN KEY (`recommendation_id`) REFERENCES `crop_recommendations` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=210 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
